report_lines.append(f"| 8 | **NCC (Normalized Cross-Corr)** | {summary['ncc_diag']['min']:.6f} | {summary['ncc_diag']['max']:.6f} | **{summary['ncc_diag']['mean']:.6f} ± {summary['ncc_diag']['std']:.6f}** | Pearson linear correlation coefficient mendekati 1.0 |")
report_lines.append(f"| 9 | **Chi-Square ($\\chi^2$) Hist. Dist.** | {summary['chi2_hist_diag']['min']:.2f} | {summary['chi2_hist_diag']['max']:.2f} | **{summary['chi2_hist_diag']['mean']:.2f} ± {summary['chi2_hist_diag']['std']:.2f}** | Divergensi bentuk histogram sangat kecil (4096 bin) |")
